@page "/settings"
@rendermode InteractiveServer
@using sv_2a7c3d9807324a779e1fe561e786858e.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="settings-nav-item @(section == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section)">
                    <span class="nav-icon">@GetSectionIcon(section)</span>
                    <span>@section</span>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastVisible)
        {
            <div class="settings-toast @(_toastIsError ? "toast-error" : "toast-success")">
                <span>@_toastMessage</span>
                <button class="btn-close btn-close-white btn-sm" @onclick="() => _toastVisible = false"></button>
            </div>
        }
    </div>
</div>

@* ===== Profile Section ===== *@
@{
    RenderFragment RenderProfileSection() =>
        @<div class="settings-section">
            <h3 class="section-title">Profile</h3>
            <p class="section-description">Manage your personal information and public profile.</p>

            <div class="profile-layout">
                <div class="avatar-area">
                    <div class="avatar-preview">
                        <img src="@_profileAvatarUrl" alt="Avatar" />
                    </div>
                    <div class="avatar-url-display">
                        <label class="form-label fw-semibold">Avatar URL</label>
                        <input type="text" class="form-control form-control-sm" value="@_profileAvatarUrl" disabled />
                    </div>
                </div>

                <div class="profile-fields">
                    <div class="mb-3">
                        <label class="form-label fw-semibold">Display Name</label>
                        <input type="text" class="form-control" @bind="_profileDisplayName" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label fw-semibold">Email</label>
                        <input type="email" class="form-control" @bind="_profileEmail" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label fw-semibold">Bio</label>
                        <textarea class="form-control" rows="4" @bind="_profileBio"></textarea>
                    </div>
                </div>
            </div>

            <div class="section-actions">
                <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save Changes
                </button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </div>;
}

@* ===== Notifications Section ===== *@
@{
    RenderFragment RenderNotificationsSection() =>
        @<div class="settings-section">
            <h3 class="section-title">Notifications</h3>
            <p class="section-description">Choose how and when you want to be notified.</p>

            <div class="toggle-group">
                <div class="toggle-row">
                    <div>
                        <div class="toggle-label">Email Notifications</div>
                        <div class="toggle-description">Receive notifications via email</div>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" role="switch" @bind="_notifEmail" />
                    </div>
                </div>
                <div class="toggle-row">
                    <div>
                        <div class="toggle-label">Push Notifications</div>
                        <div class="toggle-description">Receive push notifications on your devices</div>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" role="switch" @bind="_notifPush" />
                    </div>
                </div>
                <div class="toggle-row">
                    <div>
                        <div class="toggle-label">Weekly Digest</div>
                        <div class="toggle-description">Get a weekly summary of activity</div>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" role="switch" @bind="_notifWeeklyDigest" />
                    </div>
                </div>
            </div>

            <div class="mt-4">
                <h5 class="fw-semibold">Muted Channels</h5>
                <p class="text-muted small">Uncheck a channel to unmute it.</p>
                <div class="channel-list">
                    @if (_allChannels is not null)
                    {
                        @foreach (var channel in _allChannels)
                        {
                            var ch = channel;
                            <div class="form-check">
                                <input class="form-check-input darker-border-checkbox" type="checkbox" id="@($"ch-{ch}")"
                                       checked="@_mutedChannels.Contains(ch)"
                                       @onchange="e => ToggleMutedChannel(ch, (bool)e.Value!)" />
                                <label class="form-check-label" for="@($"ch-{ch}")">@ch</label>
                            </div>
                        }
                    }
                </div>
            </div>

            <div class="section-actions">
                <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save Preferences
                </button>
            </div>
        </div>;
}

@* ===== Security Section ===== *@
@{
    RenderFragment RenderSecuritySection() =>
        @<div class="settings-section">
            <h3 class="section-title">Security</h3>
            <p class="section-description">Protect your account with passwords and session management.</p>

            @* Change Password Panel *@
            <div class="expandable-panel">
                <button class="expandable-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span class="fw-semibold">Change Password</span>
                    <span class="expand-icon">@(_passwordPanelOpen ? "▲" : "▼")</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="expandable-body">
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword" disabled="@_saving">
                            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            @* Two-Factor Authentication *@
            <div class="toggle-group mt-4">
                <div class="toggle-row">
                    <div>
                        <div class="toggle-label">Two-Factor Authentication</div>
                        <div class="toggle-description">
                            @if (_twoFactorEnabled)
                            {
                                <span class="badge bg-success me-1">Enabled</span>
                            }
                            else
                            {
                                <span class="badge bg-warning text-dark me-1">Disabled</span>
                            }
                            Add an extra layer of security to your account
                        </div>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" role="switch" @bind="_twoFactorEnabled" />
                    </div>
                </div>
            </div>

            @if (_lastPasswordChange.HasValue)
            {
                <p class="text-muted small mt-2">
                    Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </p>
            }

            @* Active Sessions *@
            <div class="mt-4">
                <h5 class="fw-semibold">Active Sessions</h5>
                <div class="table-responsive">
                    <table class="table table-hover align-middle">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @if (_sessions is not null)
                            {
                                @foreach (var session in _sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td>
                                            @if (session.Id == _sessions.FirstOrDefault()?.Id)
                                            {
                                                <span class="badge bg-info">Current</span>
                                            }
                                            else
                                            {
                                                <button class="btn btn-outline-danger btn-sm"
                                                        @onclick="() => PromptRevokeSession(session)">
                                                    Revoke
                                                </button>
                                            }
                                        </td>
                                    </tr>
                                }
                            }
                        </tbody>
                    </table>
                </div>
            </div>

            @* Revoke Confirmation Dialog *@
            @if (_sessionToRevoke is not null)
            {
                <div class="modal-backdrop-custom" @onclick="() => _sessionToRevoke = null"></div>
                <div class="confirmation-dialog">
                    <h5>Revoke Session</h5>
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                    <div class="d-flex gap-2 justify-content-end">
                        <button class="btn btn-secondary btn-sm" @onclick="() => _sessionToRevoke = null">Cancel</button>
                        <button class="btn btn-danger btn-sm" @onclick="ConfirmRevokeSession" disabled="@_saving">
                            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Revoke
                        </button>
                    </div>
                </div>
            }
        </div>;
}

