/* ===== Layout ===== */
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 120px);
    gap: 0;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
}

/* ===== Sidebar ===== */
.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-weight: 700;
    color: #212529;
    font-size: 1.1rem;
    border-bottom: 1px solid #dee2e6;
}

.settings-nav {
    list-style: none;
    padding: 0.5rem 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.65rem 1.25rem;
    cursor: pointer;
    color: #495057;
    font-weight: 500;
    transition: background 0.15s, color 0.15s;
    border-left: 3px solid transparent;
}

    .settings-nav-item:hover {
        background: #e9ecef;
        color: #212529;
    }

    .settings-nav-item.active {
        background: #e7f1ff;
        color: #0d6efd;
        border-left-color: #0d6efd;
        font-weight: 600;
    }

.nav-icon {
    font-size: 1.1rem;
}

/* ===== Content Area ===== */
.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    position: relative;
    overflow-y: auto;
}

.settings-section {
    max-width: 800px;
}

.section-title {
    font-weight: 700;
    margin-bottom: 0.25rem;
}

.section-description {
    color: #6c757d;
    margin-bottom: 1.5rem;
}

.section-actions {
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #dee2e6;
    display: flex;
    gap: 0.75rem;
}

/* ===== Profile ===== */
.profile-layout {
    display: flex;
    gap: 2rem;
}

.avatar-area {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.75rem;
    min-width: 160px;
}

.avatar-preview {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    overflow: hidden;
    border: 3px solid #dee2e6;
    background: #f8f9fa;
}

    .avatar-preview img {
        width: 100%;
        height: 100%;
        object-fit: cover;
    }

.avatar-url-display {
    width: 100%;
}

.profile-fields {
    flex: 1;
}

/* ===== Toggle Group ===== */
.toggle-group {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 1.25rem;
}

    .toggle-row + .toggle-row {
        border-top: 1px solid #dee2e6;
    }

.toggle-label {
    font-weight: 600;
    margin-bottom: 0.1rem;
}

.toggle-description {
    font-size: 0.85rem;
    color: #6c757d;
}

/* ===== Channels ===== */
.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.5rem;
    padding: 0.75rem 0;
}

/* ===== Expandable Panel ===== */
.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
}

.expandable-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 1rem 1.25rem;
    border: none;
    background: #f8f9fa;
    cursor: pointer;
    text-align: left;
}

    .expandable-header:hover {
        background: #e9ecef;
    }

.expand-icon {
    font-size: 0.75rem;
    color: #6c757d;
}

.expandable-body {
    padding: 1.25rem;
    border-top: 1px solid #dee2e6;
}

/* ===== Confirmation Dialog ===== */
.modal-backdrop-custom {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    z-index: 1040;
}

.confirmation-dialog {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: #fff;
    border-radius: 0.5rem;
    padding: 1.5rem;
    min-width: 380px;
    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.2);
    z-index: 1050;
}

/* ===== Appearance Preview ===== */
.appearance-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
}

.preview-area {
    background: #f8f9fa;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.25rem;
    transition: all 0.3s ease;
}

.preview-label {
    font-weight: 600;
    margin-bottom: 0.75rem;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #6c757d;
}

.preview-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 0.75rem;
}

.preview-meta {
    font-size: 0.8rem;
    color: #6c757d;
    text-align: center;
}

/* Preview variants */
.preview-dark {
    background: #1e1e2e;
    border-color: #444;
    color: #e0e0e0;
}

    .preview-dark .preview-label {
        color: #adb5bd;
    }

    .preview-dark .preview-card {
        background: #2d2d3f;
        border-color: #555;
        color: #e0e0e0;
    }

    .preview-dark .preview-meta {
        color: #adb5bd;
    }

.preview-small {
    font-size: 0.8rem;
}

    .preview-small .preview-card h5 {
        font-size: 1rem;
    }

.preview-large {
    font-size: 1.1rem;
}

    .preview-large .preview-card h5 {
        font-size: 1.4rem;
    }

.preview-compact .preview-card {
    padding: 0.5rem;
}

.preview-compact .preview-area {
    padding: 0.75rem;
}

/* ===== Toast ===== */
.settings-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    padding: 0.75rem 1.25rem;
    border-radius: 0.375rem;
    color: #fff;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    z-index: 1100;
    box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.2);
    animation: slideIn 0.3s ease;
}

.toast-success {
    background: #198754;
}

.toast-error {
    background: #dc3545;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(1rem);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ===== Responsive ===== */
@media (max-width: 768px) {
    .settings-dashboard {
        flex-direction: column;
    }

    .settings-sidebar {
        width: 100%;
        min-width: auto;
        border-right: none;
        border-bottom: 1px solid #dee2e6;
    }

    .settings-nav {
        display: flex;
        overflow-x: auto;
    }

    .settings-nav-item {
        border-left: none;
        border-bottom: 3px solid transparent;
        white-space: nowrap;
    }

        .settings-nav-item.active {
            border-left-color: transparent;
            border-bottom-color: #0d6efd;
        }

    .settings-content {
        padding: 1.5rem;
    }

    .profile-layout {
        flex-direction: column;
    }

    .appearance-grid {
        grid-template-columns: 1fr;
    }
}

